/* Generated from themes/arcade.json. Do not edit; run pnpm tokens:build.
   The arcade theme on its own, for a consumer installing @gamestage/theme-arcade.
   Needs gamestage-tokens.css for the values it does not override, and its own
   font item for the families it names. */

@layer gs.base, gs.context, gs.theme;

@layer gs.theme {
  [data-gs-theme="arcade"] {
  --gs-color-background: linear-gradient(180deg,oklch(0.40 0.16 262),oklch(0.26 0.13 270));
  --gs-color-background-solid: oklch(0.40 0.16 262);
  --gs-color-surface: linear-gradient(180deg,oklch(0.50 0.17 256),oklch(0.42 0.17 264));
  --gs-color-surface-solid: oklch(0.50 0.17 256);
  --gs-color-surface-raised: linear-gradient(180deg,oklch(0.64 0.15 242),oklch(0.50 0.17 258));
  --gs-color-surface-raised-solid: oklch(0.64 0.15 242);
  --gs-color-edge: oklch(0.20 0.09 272);
  --gs-color-edge-solid: oklch(0.20 0.09 272);
  --gs-color-edge-high: oklch(0.80 0.10 228);
  --gs-color-edge-high-solid: oklch(0.80 0.10 228);
  --gs-color-ink: #ffffff;
  --gs-color-ink-solid: #ffffff;
  --gs-color-ink-secondary: oklch(0.88 0.05 240);
  --gs-color-ink-secondary-solid: oklch(0.88 0.05 240);
  --gs-color-muted: oklch(0.74 0.08 250);
  --gs-color-muted-solid: oklch(0.74 0.08 250);
  --gs-color-interactive: linear-gradient(180deg,oklch(0.87 0.17 82),oklch(0.72 0.19 52));
  --gs-color-interactive-solid: oklch(0.87 0.17 82);
  --gs-color-interactive-hover: linear-gradient(180deg,oklch(0.91 0.16 84),oklch(0.77 0.18 54));
  --gs-color-interactive-hover-solid: oklch(0.91 0.16 84);
  --gs-color-interactive-base: oklch(0.50 0.16 45);
  --gs-color-interactive-base-solid: oklch(0.50 0.16 45);
  --gs-color-selected: oklch(0.86 0.15 192);
  --gs-color-selected-solid: oklch(0.86 0.15 192);
  --gs-color-positive: linear-gradient(180deg,oklch(0.88 0.17 162),oklch(0.72 0.18 155));
  --gs-color-positive-solid: oklch(0.88 0.17 162);
  --gs-color-negative: linear-gradient(180deg,oklch(0.74 0.20 22),oklch(0.60 0.22 26));
  --gs-color-negative-solid: oklch(0.74 0.20 22);
  --gs-color-warning: oklch(0.82 0.18 62);
  --gs-color-warning-solid: oklch(0.82 0.18 62);
  --gs-color-reward: linear-gradient(180deg,oklch(0.92 0.15 96),oklch(0.80 0.18 76));
  --gs-color-reward-solid: oklch(0.92 0.15 96);
  --gs-color-player: oklch(0.86 0.15 192);
  --gs-color-player-solid: oklch(0.86 0.15 192);
  --gs-color-opponent: oklch(0.72 0.22 330);
  --gs-color-opponent-solid: oklch(0.72 0.22 330);
  --gs-color-disabled: oklch(0.38 0.06 265);
  --gs-color-disabled-solid: oklch(0.38 0.06 265);
  --gs-color-disabled-ink: oklch(0.66 0.05 260);
  --gs-color-disabled-ink-solid: oklch(0.66 0.05 260);
  --gs-color-on-accent: oklch(0.22 0.09 272);
  --gs-color-on-accent-solid: oklch(0.22 0.09 272);
  --gs-color-on-bright: oklch(0.22 0.09 272);
  --gs-color-on-bright-solid: oklch(0.22 0.09 272);
  --gs-color-shadow: rgba(0,10,40,.55);
  --gs-color-shadow-solid: rgba(0,10,40,.55);
  --gs-stroke-control: 3px;
  --gs-stroke-ui: 3px;
  --gs-type-action-font-family: var(--gs-type-font-family-display);
  --gs-type-action-font-size: 19px;
  --gs-type-action-font-weight: 900;
  --gs-type-action-text-transform-primary: uppercase;
  --gs-type-action-letter-spacing: 0.02em;
  --gs-type-display-shadow: 0 3px 0 var(--gs-color-edge);
  --gs-type-stat-font-family: var(--gs-type-font-family-display);
  --gs-type-stat-font-size: 22px;
  --gs-type-stat-font-weight: 900;
  --gs-type-score-font-family: var(--gs-type-font-family-display);
  --gs-type-score-font-size: 34px;
  --gs-type-score-font-weight: 900;
  --gs-type-score-font-variant-numeric: tabular-nums;
  --gs-type-display-font-family: var(--gs-type-font-family-display);
  --gs-type-display-font-size: 48px;
  --gs-type-display-font-weight: 800;
  --gs-type-label-font-family: var(--gs-type-font-family-interface);
  --gs-type-label-font-size: 12px;
  --gs-type-label-font-weight: 800;
  --gs-type-label-letter-spacing: 0.06em;
  --gs-type-label-text-transform: uppercase;
  --gs-type-caption-font-family: var(--gs-type-font-family-interface);
  --gs-type-caption-font-size: 11px;
  --gs-type-caption-font-weight: 600;
  --gs-type-title-font-family: var(--gs-type-font-family-display);
  --gs-type-title-font-size: 20px;
  --gs-type-title-font-weight: 900;
  --gs-type-title-line-height: 1.2;
  --gs-type-figure-font-family: var(--gs-type-font-family-display);
  --gs-type-figure-font-size: 14px;
  --gs-type-figure-font-weight: 900;
  --gs-depth-style: offset;
  --gs-depth-pressable: inset 0 3px 0 rgba(255,255,255,.45), 0 var(--gs-press-travel) 0 var(--gs-color-edge), 0 12px 20px var(--gs-color-shadow);
  --gs-depth-pressable-pressed: inset 0 3px 0 rgba(255,255,255,.45);
  --gs-depth-styles-offset-pressable: inset 0 3px 0 rgba(255,255,255,.45), 0 var(--gs-press-travel) 0 var(--gs-color-edge), 0 12px 20px var(--gs-color-shadow);
  --gs-depth-styles-offset-pressed: inset 0 3px 0 rgba(255,255,255,.45);
  --gs-depth-raised: inset 0 2px 0 var(--gs-color-edge-high), 0 5px 0 var(--gs-color-edge);
  --gs-depth-floating: 0 8px 24px var(--gs-color-shadow);
  --gs-depth-pressable-positive: inset 0 3px 0 rgba(255,255,255,.45), 0 var(--gs-press-travel) 0 var(--gs-color-edge), 0 12px 20px var(--gs-color-shadow);
  --gs-depth-pressable-positive-pressed: inset 0 3px 0 rgba(255,255,255,.45);
  --gs-size-action: 60px;
  --gs-size-action-large: 68px;
  --gs-depth-styles-squeeze-pressable: 0 0 0 var(--gs-stroke-control) var(--gs-color-edge);
  --gs-depth-styles-squeeze-pressed: 0 0 0 var(--gs-stroke-selected) var(--gs-color-interactive-solid);
  --gs-depth-styles-glow-pressable: 0 0 0 var(--gs-stroke-control) var(--gs-color-edge-high);
  --gs-depth-styles-glow-pressed: 0 0 0 var(--gs-stroke-selected) var(--gs-color-interactive-solid);
  --gs-depth-reward: 0 0 0 3px var(--gs-color-background-solid), 0 0 0 5px var(--gs-color-reward-solid), 0 0 28px oklch(0.87 0.17 92 / .45);
  }
}
